package com.example

import com.example.ExamQuestionHelper.QSpec

internal object BuddhismG11LiveExamLifeBank {
  private const val T = "බුද්ධ චරිතය හා ශ්‍රාවක චරිත"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("සිද්ධාර්ථ බෝසතාණන් වහන්සේ උපත ලැබූ ලුම්බිණි සල් උයන පිහිටියේ කුමන නගර දෙක අතරද?", "කපිලවස්තු හා දෙව්දහ", "රජගහ හා සැවැත්", "බරණැස් හා විශාලා", "කොසඹෑ හා අලව්", "ශාක්‍ය හා කෝලිය ජනපද දෙක අතර ලුම්බිණි සල් උයන පිහිටා තිබුණි."),
    q("සිද්ධාර්ථ කුමාරයා උපන් වහාම සත් පියවරක් ඇවිද ප්‍රකාශ කළ අභීත වදන් හඳුන්වන්නේ කෙසේද?", "සිංහනාදය", "ධර්ම සංගායනාව", "අධිෂ්ඨාන පාරමිතාව", "බුද්ධ භාෂිතය", "ලොවට අග්‍ර බව හඟවමින් කළ ප්‍රකාශය සිංහනාදය නම් වේ."),
    q("උපතින් සත් දිනකට පසු මහාමායා දේවිය කළුරිය කළ හෙයින් කුමරු හදා වඩා ගත්තේ කවුද?", "මහා ප්‍රජාපතී ගෝතමිය", "යසෝධරා දේවිය", "ඛේමා දේවිය", "විශාඛා සිටු දියණිය", "සුළු මව වූ මහා ප්‍රජාපතී ගෝතමිය කුමරු පෝෂණය කළාය."),
    q("සිද්ධාර්ථ කුමාරයාගේ ලක්ෂණ පරීක්ෂා කර කුමරු 'ඒකාන්තයෙන්ම බුදු වන්නේය' යි පැවසූ ලාබාලම බමුණා කවුද?", "කොණ්ඩඤ්ඤ බමුණා", "රාම බමුණා", "ධජ බමුණා", "ලක්ඛණ බමුණා", "බමුණන් අටදෙනාගෙන් ලාබාලම කොණ්ඩඤ්ඤ බමුණා එක් ඇඟිල්ලක් ඔසවා අනාවැකිය පැවසීය."),
    q("කුමරුගේ උපතින් පසු රජ මැදුරට පැමිණ සතුටින් හා දුකින් හැඬූ තවුසා කවුද?", "අසිත තවුසා", "ආලාරකාලාම තවුසා", "උද්දකරාමපුත්ත තවුසා", "භග්ගව තවුසා", "කාලදේවල හෙවත් අසිත තවුසා කුමරුගේ බුද්ධත්වය දැකීමට තමා ජීවත් නොවන බව දැන හැඬීය."),
    q("සිද්ධාර්ථ කුමරු පළමුවරට ප්‍රථම ධ්‍යානය උපදවා ගත්තේ කුමන උත්සව අවස්ථාවේදීද?", "වප් මඟුල් උත්සවයේදී", "ඇසළ උත්සවයේදී", "නැකැත් කෙළියේදී", "ජල ක්‍රීඩාවේදී", "ජම්බු රුක සෙවණේ හිඳ ආනාපානසති භාවනාවෙන් ප්‍රථම ධ්‍යානය ලැබීය."),
    q("සිද්ධාර්ථ කුමාරයාට ශිල්ප ශාස්ත්‍ර ඉගැන්වූ ප්‍රධාන ආචාර්යවරයා කවුද?", "සබ්බමිත්ත ආචාර්යවරයා", "දිසාපාමොක් ආචාර්යවරයා", "විශ්වාමිත්‍ර ආචාර්යවරයා", "කෞටිල්‍ය ආචාර්යවරයා", "කපිලවස්තුවේ සබ්බමිත්ත ඇදුරුතුමා කුමරුට ශිල්ප ඉගැන්වීය."),
    q("කුමරු ගිහිගෙය අතහැර යාමට මූලික පසුබිම සැකසූ සතර පෙර නිමිති මොනවාද?", "මහල්ලා, ලෙඩා, මළමිනිය, පැවිදි රුව", "මහල්ලා, දුගියා, රජු, පැවිදි රුව", "ලෙඩා, අන්ධයා, ගොළුවා, තවුසා", "ළදරුවා, තරුණයා, මහල්ලා, බමුණා", "උයන් කෙළියට යන අතරතුර දුටු මෙම නිමිති සතර ජීවිතයේ යථාර්ථය පෙන්වීය."),
    q("මහාභිනිෂ්ක්‍රමණය සිදු වූ දිනයේදී සිද්ධාර්ථ කුමාරයාට ලැබුණු පුත් කුමරු කවුද?", "රාහුල කුමරු", "නන්ද කුමරු", "දේවදත්ත කුමරු", "ආනන්ද කුමරු", "ඇසළ පුන් පොහෝ දින රාහුල කුමරු උපන් බව සැලවිය."),
    q("මහාභිනිෂ්ක්‍රමණය සඳහා බෝසතුන් ගමන් කළ අශ්වයා සහ රියදුරා කවුද?", "කන්ථක අශ්වයා සහ චන්න ඇමති", "සේනක අශ්වයා සහ සුමන ඇමති", "වාලාහක අශ්වයා සහ කාලුදායි ඇමති", "උච්චෛශ්‍රවස් අශ්වයා සහ මහානාම ඇමති", "කන්ථක අසු පිට නැගී චන්න ඇමති සමඟ අනෝමා ගං තෙරට වැඩම කළහ."),
    q("අනෝමා ගං තෙරදී කෙස් වැටිය කපා පැවිදි වූ බෝසතුන්ට අටපිරිකර පූජා කළේ කවුද?", "ඝටීකාර මහා බ්‍රහ්මයා", "සහම්පතී මහා බ්‍රහ්මයා", "සක්‍ර දේවේන්ද්‍රයා", "සුයාම දෙව් රජු", "කාශ්‍යප බුදුන් දවස යහළුවා වූ ඝටීකාර බ්‍රහ්මයා අටපිරිකර පිදීය."),
    q("පැවිදි වීමෙන් පසු බෝසතුන් ප්‍රථමයෙන්ම පිඬුසිඟා වැඩියේ කුමන නගරයේදීද?", "රජගහ නුවර", "විශාලා මහනුවර", "සැවැත් නුවර", "බරණැස් නුවර", "මගධ රාජ්‍යයේ අගනුවර වූ රජගහ නුවර පිඬුසිඟා වැඩම කළහ."),
    q("රජගහ නුවරදී බෝසතුන් මුණගැසී සිය රාජ්‍යයෙන් අඩක් පවා දීමට කැමති වූ රජු කවුද?", "බිම්බිසාර රජු", "පසේනදී කොසොල් රජු", "අජාසත් රජු", "උදේනි රජු", "බිම්බිසාර රජු බුද්ධත්වයෙන් පසු තම රටට වඩින ලෙස ආරාධනා කළේය."),
    q("බෝසතුන්ට ආකිඤ්චඤ්ඤායතන සමාපත්තිය ඉගැන්වූ පළමු ගුරුවරයා කවුද?", "ආලාරකාලාම තවුසා", "උද්දකරාමපුත්ත තවුසා", "භග්ගව තවුසා", "සංජය පිරිවැජියා", "ආලාරකාලාම වෙතින් ආකිඤ්චඤ්ඤායතනය දක්වා ධ්‍යාන උගත්හ."),
    q("උද්දකරාමපුත්ත තවුසා යටතේ බෝසතුන් ප්‍රගුණ කළ ඉහළම සමාපත්තිය කුමක්ද?", "නේවසඤ්ඤානාසඤ්ඤායතනය", "ආකාසානඤ්චායතනය", "විඤ්ඤාණඤ්චායතනය", "නිරෝධ සමාපත්තිය", "අරූපාවචර අටවන සමාපත්තිය වූ නේවසඤ්ඤානාසඤ්ඤායතනය ඉගෙන ගත්හ."),
    q("දුෂ්කරක්‍රියා සමයේ බෝසතුන් වාසය කළ උරුවෙලාවේ සේනානි නියම්ගම අසල ගංගාව කුමක්ද?", "නේරංජනා නදිය", "අනෝමා නදිය", "අචිරවතී නදිය", "සරභූ නදිය", "නේරංජනා ගං තෙර උරුවෙල වන ලැහැබේ වසර හයක් දුෂ්කරක්‍රියා කළහ."),
    q("බෝසතුන්ට දුෂ්කරක්‍රියා කාලයේ උපස්ථාන කළ පස්වග තවුසන්ගේ ප්‍රධානියා කවුද?", "කොණ්ඩඤ්ඤ තවුසා", "වප්ප තවුසා", "භද්දිය තවුසා", "අස්සජී තවුසා", "කොණ්ඩඤ්ඤ, වප්ප, භද්දිය, මහානාම, අස්සජී යන පස්දෙනා උපස්ථාන කළහ."),
    q("බුද්ධත්වයට පත්වීමට පෙර සුජාතා සිටු දියණිය බෝසතුන්ට පූජා කළේ කුමක්ද?", "රන් තලියක කිරිපිඬු දානය", "මී පිඬු දානය", "කැඳ දානය", "පලතුරු දානය", "අජපල් නුගරුක මුලදී සුජාතාව කිරිපිඬු පූජා කළාය."),
    q("රන් තලිය නේරංජනා නදියේ උඩුගං බලා ගිය පසු බෝසතුන් බෝධි මූලයට වඩිද්දී කුස තණ මිටි පිදුවේ කවුද?", "සොත්ථිය බමුණා", "සුජාතා දේවිය", "තපස්සු භල්ලුක", "සුදත්ත සිටුතුමා", "සොත්ථිය නම් බමුණාගෙන් ලද කුස තණ අතුරා වජ්‍රාසනය සකසා ගත්හ."),
    q("සම්මා සම්බුද්ධත්වයට පත්වන රාත්‍රියේ මධ්‍යම යාමයේදී උන්වහන්සේ අවබෝධ කළ ඥානය කුමක්ද?", "චුතූපපාත ඥානය", "පුබ්බේනිවාසානුස්සති ඥානය", "ආසවක්ඛය ඥානය", "පරචිත්ත විජානන ඥානය", "පෙර යමේ පුබ්බේනිවාස, මැදියමේ චුතූපපාත, පැසුළු යමේ ආසවක්ඛය ඥාන උපදවා ගත්හ."),
    q("බුදුරජාණන් වහන්සේ බුද්ධත්වයෙන් දෙවන සතිය ගත කළේ කුමන පූජාව පවත්වමින්ද?", "අනිමිසලෝචන පූජාව", "රුවන් සක්මන් පූජාව", "රතනඝර සතිය", "මුචලින්ද සතිය", "ජය ශ්‍රී මහා බෝධිය දෙස ඇසිපිය නොහෙළා සතියක් බලා සිට කෘතගුණ දැක්වූහ."),
    q("බුද්ධත්වයෙන් පසු බුදුරදුන් සත් සතියෙන් සතරවන සතියේ අභිධර්මය මෙනෙහි කළ ස්ථානය කුමක්ද?", "රතනඝරය", "අජපල් නුගරුක මුල", "මුචලින්ද විල අසල", "රාජායතන කිරිපලු රුක මුල", "රතනඝරයේදී සම්මර්ශනය කරද්දී ෂඩ්වර්ණ බුද්ධ රශ්මිය විහිදිණි."),
    q("බුදුරදුන්ට ප්‍රථමයෙන් විලඳ හා මීපිඬු පූජා කළ වෙළඳ දෙබෑයන් කවුද?", "තපස්සු හා භල්ලුක", "අනේපිඬු හා මිගාර", "නකුලපිතා හා නකුලමාතා", "මහාලි හා සීහ", "උක්කලා ජනපදයේ වෙළඳුන් දෙදෙනා ද්වේවාචික උපාසකයන් වූහ."),
    q("ධර්ම දේශනා කිරීමට බුදුරදුන්ට ආරාධනා කළ මහා බ්‍රහ්මයා කවුද?", "සහම්පතී මහා බ්‍රහ්මයා", "ඝටීකාර මහා බ්‍රහ්මයා", "සනංකුමාර මහා බ්‍රහ්මයා", "බක බ්‍රහ්මයා", "ධර්මය අවබෝධ කරන්නන් සිටින බව පවසමින් සහම්පතී බ්‍රහ්මයා ආරාධනා කළේය."),
    q("බුදුරජාණන් වහන්සේ බරණැසට වඩින අතරමගදී මුණගැසුණු ආජීවකයා කවුද?", "උපක ආජීවකයා", "පූරණ කස්සප", "මක්ඛලී ගෝසාල", "අජිත කේසකම්බල", "බුදුරදුන් සමඟ කෙටි සංවාදයක යෙදුණු උපක පසුව අනාගාමී විය."),
    q("ප්‍රථම ධර්ම දේශනාවෙන් පසු පළමුවෙන්ම ධර්මචක්ෂුස (සෝවාන් ඵලය) ලැබූ හිමියන් කවුද?", "අඤ්ඤාකොණ්ඩඤ්ඤ හිමි", "භද්දිය හිමි", "වප්ප හිමි", "මහානාම හිමි", "අසූ කෝටියක් බ්‍රහ්ම දෙවියන් සමඟ කොණ්ඩඤ්ඤ තෙරුන් සෝවාන් විය."),
    q("පස්වග මහණුන් අරහත්වයට පත්වූයේ කුමන සූත්‍ර දේශනාව අවසානයේදීද?", "අනත්තලක්ඛණ සූත්‍රය", "ධම්මචක්කප්පවත්තන සූත්‍රය", "ආදිත්තපරියාය සූත්‍රය", "මහාසමය සූත්‍රය", "පංචස්කන්ධයේ අනාත්ම ස්වභාවය දෙසූ අනත්තලක්ඛණ සූත්‍රයෙන් රහත් වූහ."),
    q("බුදුරදුන් හමුවේ 'නිදුකාණෙනි, මෙහි ඒකාන්තයෙන් උවදුරු ඇත' යි පවසමින් පැමිණ පැවිදි වූ කුලපුත්‍රයා කවුද?", "යස කුලපුත්‍රයා", "විමල කුලපුත්‍රයා", "සුබාහු කුලපුත්‍රයා", "පුණ්ණජි කුලපුත්‍රයා", "බරණැස සිටු පුත් යස කුලපුත්‍රයා පැවිදි වී රහත් විය."),
    q("බුද්ධ ශාසනයේ ප්‍රථම තෙරුවන් සරණ ගිය උපාසක උපාසිකාවන් වූයේ කවුරුන්ද?", "යස සිටු පුත්‍රයාගේ පියා හා මව", "බිම්බිසාර රජු හා ඛේමා දේවිය", "සුදොවුන් රජු හා ගෝතමිය", "අනේපිඬු සිටු හා සුමනා දේවිය", "යස හිමියන්ගේ පියා, මව හා පැරණි බිරිඳ ත්‍රිවාචික සරණ ගියහ."),
    q("උරුවෙල කාශ්‍යප ප්‍රමුඛ දහසක් ජටිල පිරිස රහත් බවට පත්වූ දේශනාව කුමක්ද?", "ආදිත්තපරියාය සූත්‍රය", "සච්චවිභංග සූත්‍රය", "අංගුලිමාල සූත්‍රය", "චූලරාහුලෝවාද සූත්‍රය", "ගයා ශීර්ෂයේදී සියල්ල ගිනිගෙන ඇති බව දෙසූ ආදිත්තපරියාය සූත්‍රය දේශනා කළහ."),
    q("බිම්බිසාර රජු බුදුරදුන් ප්‍රමුඛ මහා සංඝයාට පූජා කළ ප්‍රථම ආරාමය කුමක්ද?", "වේළුවනාරාමය", "ජේතවනාරාමය", "පූර්වාරාමය", "ඝෝෂිතාරාමය", "රජගහ නුවර වේළුවන උයන බුද්ධ ශාසනයේ ප්‍රථම ආරාම පූජාවයි."),
    q("සැරියුත් සහ මුගලන් හිමිවරුන් පැවිදි වීමට පෙර අනුගමනය කළ පරිබ්‍රාජක ආචාර්යවරයා කවුද?", "සංජය බෙල්ලට්ඨිපුත්ත", "නිගණ්ඨ නාථපුත්ත", "පකුධ කච්චායන", "අජිත කේසකම්බල", "උපතිස්ස හා කෝලිත මුලින් සංජය පිරිවැජියාගේ ශිෂ්‍යයෝ වූහ."),
    q("උපතිස්ස පරිබ්‍රාජකයාට 'යේ ධම්මා හේතුප්පභවා' ගාථාව වදාළ රහතන් වහන්සේ කවුද?", "අස්සජී මහරහතන් වහන්සේ", "භද්දිය මහරහතන් වහන්සේ", "වප්ප මහරහතන් වහන්සේ", "මහානාම මහරහතන් වහන්සේ", "අස්සජී හිමියන්ගේ ඉරියව් දැක පැහැදුණු උපතිස්ස ධර්මය අසා සෝවාන් විය."),
    q("සැරියුත් මහරහතන් වහන්සේට බුදුරදුන් විසින් පිරිනමන ලද අග්‍රස්ථානය කුමක්ද?", "මහා ප්‍රඥාවන්ත භික්ෂූන් අතර අග්‍ර", "මහා ඍද්ධිමත් භික්ෂූන් අතර අග්‍ර", "ධුතාංගධාරී භික්ෂූන් අතර අග්‍ර", "විනයධර භික්ෂූන් අතර අග්‍ර", "සැරියුත් හිමියන් ධර්ම සේනාපති හා දකුණත් අග්‍රශ්‍රාවක වූහ."),
    q("මුගලන් මහරහතන් වහන්සේ බුදු සසුනේ කුමන තනතුරකින් පිදුම් ලැබුවේද?", "වමත් අග්‍රශ්‍රාවක හා ඍද්ධිමතුන් අතර අග්‍ර", "දකුණත් අග්‍රශ්‍රාවක හා විනයධර අග්‍ර", "ධර්ම කථිකයන් අතර අග්‍ර", "බහුශ්‍රුතයන් අතර අග්‍ර", "නන්දෝපනන්ද නා දමනය ආදී ඍද්ධි බල පෑ මුගලන් හිමි ඍද්ධිමතුන් අතර අග්‍ර වූහ."),
    q("බුදුරදුන් කපිලවස්තුවට වැඩම කරවීම සඳහා පණිවිඩ රැගෙන ගොස් පැවිදිව රහත් වූ ඇමතියා කවුද?", "කාලුදායි ඇමති", "චන්න ඇමති", "වස්සකාර ඇමති", "සුනීධ ඇමති", "සිදුහත් කුමරු සමඟ එකම දින උපන් කාලුදායි හිමි ඥාතීන්ට මඟ පෑදූහ."),
    q("කපිලවස්තු නුවරදී ශාක්‍යයන්ගේ මානය බිඳීමට බුදුරදුන් පෑ ප්‍රාතිහාර්යය කුමක්ද?", "යමා මහ පෙළහර", "ආකාස ගමන", "චක්‍රවර්ති ප්‍රාතිහාර්යය", "තේජෝ කසිණ පෙළහර", "ජලය හා ගින්න එකවර විහිදුවමින් යමා මහ පෙළහර පෑ සේක."),
    q("සැවැත් නුවර ජේතවනාරාමය රන් කහවණු අතුරා මිලදී ගෙන පූජා කළ සිටුතුමා කවුද?", "අනේපිඬු සිටුතුමා", "මිගාර සිටුතුමා", "ඝෝෂිත සිටුතුමා", "ධනංජය සිටුතුමා", "සුදත්ත හෙවත් අනේපිඬු සිටුතුමා ජේත කුමරුගෙන් උයන මිලදී ගත්තේය."),
    q("පූර්වාරාම විහාරය ඉදිකර බුදුපාමොක් මහා සංඝයාට පූජා කළ මහා උපාසිකාව කවුද?", "විශාඛා මහා උපාසිකාව", "බන්ධුල මල්ලිකාව", "කාණාමාතාව", "සුප්පාවාසා උපාසිකාව", "මිගාරමාතා නම් ලද විශාඛාවෝ පූර්වාරාමය කරවූහ."),
    q("භික්ෂුණී ශාසනය ආරම්භ කිරීමට මූලික වූ අෂ්ට ගරු ධර්ම පිළිගත් තෙරණිය කවුද?", "මහා ප්‍රජාපතී ගෝතමී තෙරණිය", "යසෝධරා තෙරණිය", "ඛේමා තෙරණිය", "ධම්මදින්නා තෙරණිය", "ආනන්ද හිමියන්ගේ මැදිහත්වීමෙන් කාන්තා පැවිද්ද හිමිවිය."),
    q("භික්ෂුණීන් අතරින් 'මහා ප්‍රඥාවන්තියන් අතර අග්‍ර' තනතුර ලැබූ තෙරණිය කවුද?", "ඛේමා මහරහත් තෙරණිය", "උප්පලවණ්ණා තෙරණිය", "පටාචාරා තෙරණිය", "කුණ්ඩලකේසී තෙරණිය", "රූප මදයෙන් සිටි ඛේමා බිසව බුදු බණ අසා රහත් වූවාය."),
    q("භික්ෂුණීන් අතරින් 'ඍද්ධිමතුන් අතර අග්‍ර' තනතුර ලැබූ තෙරණිය කවුද?", "උප්පලවණ්ණා තෙරණිය", "ඛේමා තෙරණිය", "ගෝතමී තෙරණිය", "භද්දා කාපිලානි තෙරණිය", "උප්පලවණ්ණා මහරහත් තෙරණිය ඍද්ධි බලයෙන් අග්‍ර වූවාය."),
    q("මළ දරුවාට බෙහෙතක් ලෙස නොමළ ගෙයකින් අබ ඇට සෙවීමට ගොස් අනිත්‍යතාව අවබෝධ කළ කාන්තාව කවුද?", "කිසාගෝතමී", "පටාචාරා", "සෝමා", "විශාඛා", "සෑම නිවසකම මරණය සිදුව ඇති බව දැන කිසාගෝතමිය සෝවාන් වූවාය."),
    q("එකම දිනකදී ස්වාමියා, දරුවන් දෙදෙනා, මව්පියන් හා සොහොයුරා අහිමි වී උමතු බවට පත්ව පසුව විනයධර තෙරණියක් වූයේ කවුද?", "පටාචාරා තෙරණිය", "කිසාගෝතමී තෙරණිය", "සුභා තෙරණිය", "අම්බපාලි තෙරණිය", "පටාචාරා තෙරණිය විනයධර භික්ෂුණීන් අතර අග්‍ර වූවාය."),
    q("රන්වන් හිසකෙස්, වයස්ගත වීම ආදිය ගැන පිළිකුල් භාවනාවෙන් රහත් වූ විශාලා මහනුවර නගර ශෝභිනිය කවුද?", "අම්බපාලි තෙරණිය", "පදුමාවතී තෙරණිය", "සිරිමා තෙරණිය", "සාලවතී තෙරණිය", "අම්බපාලිය තම අඹ උයන බුදුසසුනට පූජා කර පැවිදි වූවාය."),
    q("ධර්ම භාණ්ඩාගාරික හා බහුශ්‍රුතයන් අතර අග්‍ර යන තනතුරු ලැබූ රහතන් වහන්සේ කවුද?", "ආනන්ද මහරහතන් වහන්සේ", "උපාලි මහරහතන් වහන්සේ", "මහා කාශ්‍යප හිමි", "රේවත හිමි", "වසර 25ක් බුදුරදුන්ට අග්‍ර උපස්ථායක ලෙස ආනන්ද හිමි සේවය කළහ."),
    q("දහතුන් ධුතාංගධාරී භික්ෂූන් අතර අග්‍රස්ථානය ලැබූ මහතෙරුන් වහන්සේ කවුද?", "මහා කාශ්‍යප මහරහතන් වහන්සේ", "මහා කච්චායන හිමි", "කුමාර කාශ්‍යප හිමි", "පිණ්ඩෝල භාරද්වාජ හිමි", "බුදුරදුන් සමඟ සිවුරු මාරු කරගත් එකම ශ්‍රාවකයා මහා කාශ්‍යප හිමියන්ය."),
    q("ශාසනයේ සික්ඛාකාමී (ශික්ෂා ගරුක) භික්ෂූන් අතර අග්‍ර වූ සත් හැවිරිදි පැවිද්දා කවුද?", "රාහුල හිමි", "සෝපාක හිමි", "සංකිච්ච හිමි", "නිග්‍රෝධ හිමි", "දිනපතා උදෑසන වැලි මිටක් ගෙන අවවාද පැතූ රාහුල හිමි සික්ඛාකාමී අග්‍ර විය."),
    q("විනයධර භික්ෂූන් අතර අග්‍රස්ථානය ලබා පළමු සංගායනාවේදී විනය පිටකය සංගායනා කළේ කවුද?", "උපාලි මහරහතන් වහන්සේ", "ආනන්ද මහරහතන් වහන්සේ", "දබ්බ මල්ලපුත්ත හිමි", "වක්කලී හිමි", "ශාක්‍ය කුමාරවරුන්ට පෙර පැවිදි වූ උපාලි හිමි විනයධර අග්‍ර වූහ."),
    q("දිවැස් ඇති (දිබ්බචක්ඛු) භික්ෂූන් අතර අග්‍රස්ථානය ලැබූ මහරහතන් වහන්සේ කවුද?", "අනුරුද්ධ හිමි", "පිලින්දවච්ඡ හිමි", "රට්ඨපාල හිමි", "මෝඝරාජ හිමි", "දිවැස් ඥානයෙන් අග්‍ර වූ අනුරුද්ධ හිමි කුසිනාරාවේදී බුදුන් සමීපයේ සිටියහ."),
    q("බුදුරදුන්ගේ විශාල සේවාවක් සිදු කළ රාජකීය වෛද්‍යවරයා කවුද?", "ජීවක කෝමාරභච්ච", "සුශ්‍රැත", "චරක", "ධන්වන්තරී", "අඹ උයන පූජා කළ ජීවක වෙදතුමා සංඝයාට වෛද්‍ය සේවා සැපයීය."),
    q("බුදුදහම වැළඳගෙන දැහැමින් රාජ්‍ය පාලනය කළ කොසොල් රජුගේ අගමෙහෙසිය කවුද?", "මල්ලිකා දේවිය", "වාසභඛත්තියාව", "වේදේහි දේවිය", "සාමාවතී දේවිය", "අසදෘශ දානය සංවිධානය කිරීමට මල්ලිකා දේවිය කොසොල් රජුට උපදෙස් දුන්නාය."),
    q("කසළ ශෝධකයෙකු ලෙස කුලහීන යැයි සැලකූවත් බුදු සසුනේ පැවිදිව රහත් වූ භික්ෂුව කවුද?", "සුනීත හිමි", "සෝපාක හිමි", "චුල්ලපන්ථක හිමි", "රේවත හිමි", "කුල භේදයෙන් තොරව සුනීත හිමිට බුදු සසුනේ පැවිද්ද හිමිවිය."),
    q("අමු සොහොනක ගැටගසා දමා සිටියදී බුදුරදුන්ගේ මහා කරුණාවෙන් මුදාගෙන පැවිදි කළ දරුවා කවුද?", "සෝපාක", "සුනීත", "නන්ද", "සීවලී", "සත් හැවිරිදි සෝපාක මෙත්තා භාවනාවෙන් රහත් ඵලයට පත්විය."),
    q("සිව් පේළි ගාථාවක් පවා මතක තබා ගැනීමට නොහැකිව සිට සුදු රෙදි කඩක් පිරිමදිමින් අනිත්‍යය දැක රහත් වූ හිමියන් කවුද?", "චුල්ලපන්ථක හිමි", "මහාපන්ථක හිමි", "බාහිය දාරුචීරිය", "කුමාර කාශ්‍යප හිමි", "මනෝමය කාය මැවීමෙන් අග්‍ර චුල්ලපන්ථක හිමි ජීවකගේ දානයට වැඩම කළහ."),
    q("දරුණු සොරෙකු හා මිනීමරුවෙකු ලෙස සිට බුදුරදුන්ගේ අනුකම්පාවෙන් දමනය වූයේ කවුද?", "අංගුලිමාල හිමි", "ආලවක යක්ෂයා", "නාලාගිරි ඇතු", "සච්චක පරිබ්‍රාජක", "මව මැරීමට ගිය අහිංසක බුදුන් දැක අංගුලිමාල හිමි නමින් රහත් විය."),
    q("ප්‍රත්‍යලාභී භික්ෂූන් අතර අග්‍රස්ථානය ලැබූ මහරහතන් වහන්සේ කවුද?", "සීවලී මහරහතන් වහන්සේ", "මහා කච්චායන හිමි", "පූර්ණ මෛත්‍රායණීපුත්ත හිමි", "බක්කුල හිමි", "සීවලී හිමියන් සිටි තැන කිසිදා දානමාන ආදියෙන් අඩුවක් නොවීය."),
    q("සංක්ෂිප්ත ධර්ම දේශනා විස්තර කර දීමෙහි අග්‍රස්ථානය ලැබූ හිමියන් කවුද?", "මහා කච්චායන හිමි", "මහා කොට්ඨිත හිමි", "සෝණ කුටිකණ්ණ හිමි", "පුණ්ණ හිමි", "කෙටියෙන් දෙසූ දහම විස්තර කිරීමෙන් මහා කච්චායන හිමි අග්‍ර වූහ."),
    q("ධර්ම කථිකයන් අතර අග්‍රස්ථානය ලැබූ මහරහතන් වහන්සේ කවුද?", "පුණ්ණ මන්තානිපුත්ත හිමි", "වංගීස හිමි", "කුමාර කාශ්‍යප හිමි", "සුභූති හිමි", "විචිත්‍ර ධර්ම කථිකයන් අතර කුමාර කාශ්‍යප හිමිද, ධර්ම කථිකයන් අතර පුණ්ණ හිමිද අග්‍ර වූහ."),
    q("මධුර ස්වරයෙන් යුතු භික්ෂූන් අතර අග්‍රස්ථානය ලැබූ රහතන් වහන්සේ කවුද?", "ලකුණ්ඨක භද්දිය හිමි", "සෝණ කෝලිවිස හිමි", "භද්දිය කාලිගෝධාපුත්ත හිමි", "රාධ හිමි", "ලකුණ්ඨක භද්දිය හිමියන්ගේ කටහඬ අතිශය මිහිරි විය."),
    q("වීර්යවන්ත භික්ෂූන් අතර අග්‍රස්ථානය ලබා වීණාවේ තත් උපමාවෙන් අවවාද ලැබූ හිමියන් කවුද?", "සෝණ කෝලිවිස හිමි", "කිම්බිල හිමි", "නන්ද හිමි", "භගු හිමි", "මධ්‍යම ප්‍රතිපදාවෙන් වීර්යය වැඩීමේ උපමාව බුදුරදුන් සෝණ හිමිට දෙසූහ."),
    q("කුලපුත්‍රයන් සුගතියට පමුණුවන ගුණවත් උපාසකයන් අතර අග්‍ර වූයේ කවුද?", "හත්ථක ආලවක උපාසක", "චිත්ත ගහපති", "උග්ග ගහපති", "මහානාම ශාක්‍ය", "සතර සංග්‍රහ වස්තුවලින් පිරිස් දිනූ හත්ථක ආලවක පිරිස් සංග්‍රහයෙන් අග්‍ර විය."),
    q("ධර්ම කථික ගිහි උපාසකයන් අතර අග්‍රස්ථානය ලැබූ උපාසකතුමා කවුද?", "චිත්ත ගහපති", "අනේපිඬු සිටුතුමා", "මහානාම ශාක්‍ය", "ජීවක වෛද්‍යවරයා", "මච්ඡිකාසණ්ඩයේ චිත්ත ගහපතිතුමා ධර්ම කථික උපාසකයන් අතර අග්‍ර විය."),
    q("නිරෝගී භික්ෂූන් අතර අග්‍රස්ථානය ලැබූ අවුරුදු 160ක් ජීවත් වූ මහරහතන් වහන්සේ කවුද?", "බක්කුල මහරහතන් වහන්සේ", "මහා කාශ්‍යප හිමි", "ආනන්ද හිමි", "අනුරුද්ධ හිමි", "පෙර කුසල බලයෙන් බක්කුල හිමියන්ට කිසිදු රෝගයක් නොවැළඳුණි."),
    q("බුදුරදුන්ගේ සමීපතම පැවිදි ඥාතියෙකු වී සිට පසුව සංඝභේදය ඇති කිරීමට උත්සාහ කළේ කවුද?", "දේවදත්ත හිමි", "කෝකාලික හිමි", "ඡන්න හිමි", "උදායි හිමි", "පංච වරය ඉල්ලා සංඝ භේදයට තැත් කළ දේවදත්ත පසුතැවිලි වී මිය ගියේය."),
    q("දේවදත්ත හිමියන්ගේ උසිගැන්වීමෙන් සිය පියා වූ බිම්බිසාර රජු සිරගත කළේ කවුද?", "අජාසත් රජු", "උදයභද්‍ර කුමරු", "විඩූඩභ කුමරු", "චණ්ඩපජ්ජෝත රජු", "පසුව ජීවකගේ මගපෙන්වීමෙන් සාමඤ්ඤඵල සූත්‍රය අසා අජාසත් රජු පැහැදුණි."),
    q("බුදුරදුන් කෙරෙහි අචල ශ්‍රද්ධාවෙන් කටයුතු කර සැමියා ඇතුළු සිරගත වූ පිරිස රැකගත් උපාසිකාව කවුද?", "සාමාවතී දේවිය", "මාගන්දියා", "චිංචිමානවිකාව", "සුන්දරී පරිබ්‍රාජිකාව", "මෛත්‍රී විහරණයෙන් අග්‍ර උපාසිකාව සාමාවතියයි."),
    q("බුදුරජාණන් වහන්සේ වස් කාලය තුළ දෙවියන්ට අභිධර්මය දේශනා කළේ කුමන දෙව්ලොවදීද?", "තව්තිසා දෙව්ලොව", "තුසිත දෙව්ලොව", "යාම දෙව්ලොව", "නිම්මාණරතී දෙව්ලොව", "මාතෘ දිව්‍ය පුත්‍රයා ප්‍රමුඛ දෙවියන්ට තව්තිසාවේදී අභිධර්මය දේශනා කළහ."),
    q("තව්තිසා දෙව්ලොවින් බුදුරදුන් මිනිස් ලොවට වැඩම කළ නගරය කුමක්ද?", "සංකස්ස පුරය", "සැවැත් නුවර", "රජගහ නුවර", "කොසඹෑ නුවර", "වප් පුන් පොහෝ දින දේවාවරෝහණය සංකස්ස පුරයේදී සිදුවිය."),
    q("බුදුරදුන් විසින් අන්තිම වස් කාලය ගත කරන ලද්දේ කුමන ගමේදීද?", "බේළුව ගමේදී", "චාපාල චේතිය අසල", "පාවා නුවරදී", "කුසිනාරා නුවරදී", "විශාලා නුවර අසල බේළුව ගමේදී බුදුරදුන් අවසන් වස් විසූහ."),
    q("බුදුරදුන් ආයු සංස්කාරය අත්හැරීම ප්‍රකාශ කළේ කුමන ස්ථානයේදීද?", "චාපාල චේතියේදී", "වේළුවනාරාමයේදී", "ජේතවනාරාමයේදී", "සාරානාත්හිදී", "නවම් පොහෝ දින චාපාල චේතියේදී තෙමසකින් පිරිනිවන් පාන බව වදාළහ."),
    q("බුදුරජාණන් වහන්සේට අවසන් දානය වූ සූකර මද්දවය පිළිගැන්වූයේ කවුද?", "චුන්ද කර්මාර පුත්‍රයා", "සුජාතා සිටු දියණිය", "පුක්කුස මල්ල පුත්‍රයා", "වේරංජ බමුණා", "පාවා නුවර චුන්ද කර්මාර පුත්‍රයාගේ අඹ උයනේදී අවසන් දානය වැළඳූහ."),
    q("බුදුරජාණන් වහන්සේගේ අවසන් පැවිදි ශ්‍රාවකයා ලෙස සසුන්ගත වී රහත් වූයේ කවුද?", "සුභද්‍ර පරිබ්‍රාජකයා", "මල්ල රජදරුවන්", "උපවාන හිමි", "ඡන්න හිමි", "කුසිනාරාවේදී බුදුන් හමුවූ සුභද්‍ර අවසන් ශ්‍රාවකයා විය."),
    q("මහා පරිනිර්වාණය සිදු වූයේ කුමන රජදරුවන්ගේ උපවත්තන සල් උයනේදීද?", "මල්ල රජදරුවන්ගේ", "ලිච්ඡවී රජදරුවන්ගේ", "ශාක්‍ය රජදරුවන්ගේ", "වජ්ජි රජදරුවන්ගේ", "කුසිනාරා නුවර මල්ල රජදරුවන්ගේ උපවත්තන සල් උයනේදී පිරිනිවන් පෑහ."),
    q("බුදුරදුන්ගේ අවසන් බුද්ධ වචනය වූ 'හන්දදානි භික්ඛවේ...' යනුවෙන් අවධාරණය කළේ කුමක්ද?", "අප්‍රමාදව කුසල් සම්පාදනය කරන ලෙස", "දන් දීමට ප්‍රමුඛත්වය දෙන ලෙස", "මහා විහාර ඉදි කරන ලෙස", "වන්දනා ගමන් යන ලෙස", "සියලු සංස්කාර වෙනස් වන සුළු බැවින් අප්‍රමාදයෙන් සම්පාදනය කරන්නැයි වදාළහ."),
    q("බුදුරදුන්ගේ ශ්‍රී දේහය ආදාහනය කිරීමට අවසන් ගෞරව දක්වා පැමිණි මහතෙරුන් වහන්සේ කවුද?", "මහා කාශ්‍යප හිමි", "ආනන්ද හිමි", "අනුරුද්ධ හිමි", "උපාලි හිමි", "පාවා නුවර සිට වැඩම කළ මහා කාශ්‍යප හිමි චිතකයට වැඳ ගෞරව කළහ."),
    q("බුදුරජාණන් වහන්සේගේ ධාතූන් වහන්සේලා අට කොටසකට සමසේ බෙදා දුන් බ්‍රාහ්මණ පඬිවරයා කවුද?", "ද්‍රෝණ බමුණා", "සෝණදණ්ඩ බමුණා", "කූටදන්ත බමුණා", "ජානුස්සෝණි බමුණා", "ධාතු කෝලාහලය සංසිඳුවමින් ද්‍රෝණ බමුණා ධාතූන් අට කොටසකට බෙදීය."),
    q("කාලුදායි තෙරුන් බුදුරදුන්ට කපිලවස්තුවට වැඩම කරන ලෙස ආරාධනා කළේ කුමන පොහෝ දිනයකදීද?", "මැදින් පුන් පොහෝ දින", "නවම් පුන් පොහෝ දින", "දුරුතු පුන් පොහෝ දින", "බක් පුන් පොහෝ දින", "වසන්ත කාලයේ සුන්දරත්වය වනමින් මැදින් පොහෝ දින ආරාධනා කළහ."),
    q("සැරියුත් මුගලන් හිමිවරුන්ට අග්‍රශ්‍රාවක තනතුරු පිරිනමන ලද්දේ කුමන පොහෝ දිනයකදීද?", "නවම් පුන් පොහෝ දින", "වෙසක් පුන් පොහෝ දින", "ඇසළ පුන් පොහෝ දින", "ඉල් පුන් පොහෝ දින", "වේළුවනාරාමයේදී නවම් පොහෝ දින ප්‍රථම සංඝ සන්නිපාතයේදී තනතුරු දුන්හ."),
    q("බුදුරජාණන් වහන්සේ කාන්තා පැවිද්දට අනුමැතිය ලබා දුන්නේ කුමන පොහෝ දිනකදීද?", "බිනර පුන් පොහෝ දින", "නිකිණි පුන් පොහෝ දින", "වප් පුන් පොහෝ දින", "උඳුවප් පුන් පොහෝ දින", "විශාලා මහනුවර කූටාගාර ශාලාවේදී බිනර පොහෝ දින අනුමැතිය ලැබුණි."),
    q("සුළු මවගේ පුත්‍රයා වූ නන්ද කුමරු පැවිදි වූයේ කුමන කාර්යයක් අතහැරද?", "අභිෂේක මංගල්‍යය හා විවාහ උත්සවය", "යුද සේනාධිපති තනතුර", "වෙළඳ ගමන", "වන්දනා ගමන", "ජනපද කල්‍යාණිය සමඟ විවාහ උත්සව දිනයේ බුදුරදුන් පසුපස ගොස් පැවිදි විය."),
    q("ශාක්‍ය කුමාරවරුන් සමඟ පැවිදි වීමට ගොස් මුලින්ම පැවිද්ද ලැබූ කුලයෙන් පහත් යැයි සැලකූ ශිල්පියා කවුද?", "උපාලි කරණවෑමියා", "සුනීත කසළ ශෝධකයා", "චුන්ද කම්මල්කරු", "ඝටීකාර කුඹල්කරු", "උපාලි කරණවෑමියා මුලින්ම පැවිදි කිරීමෙන් ශාක්‍යයන්ගේ මානය දුරු කළහ."),
    q("වචී පරම හෙවත් මුසාවාදයෙන් වැළකී සත්‍යවාදී වූ අවුරුදු හතක සාමණේරයන් කවුද?", "රාහුල සාමණේරයන්", "සෝපාක සාමණේරයන්", "තිස්ස සාමණේරයන්", "සංකිච්ච සාමණේරයන්", "අම්බලට්ඨිකා රාහුලෝවාද සූත්‍රයෙන් බොරු කීමේ ආදීනව රාහුල හිමිට දෙසූහ."),
    q("රාජ බියෙන් තොරව වනයේ භාවනාවෙන් ලද සැපය ගැන 'අහෝ සුඛං' යන උදානය පළ කළ තෙරුන් කවුද?", "භද්දිය හිමි", "අනුරුද්ධ හිමි", "නන්ද හිමි", "කිම්බිල හිමි", "භද්දිය රජු රාජ්‍ය සැපයට වඩා පැවිදි සුවය අගය කරමින් උදානය පළ කළේය."),
    q("බුදුරදුන් ලක්දිවට ප්‍රථම වරට වැඩම කළේ කුමන පොහෝ දිනකදීද?", "දුරුතු පුන් පොහෝ දින", "බක් පුන් පොහෝ දින", "වෙසක් පුන් පොහෝ දින", "පොසොන් පුන් පොහෝ දින", "බුද්ධත්වයෙන් නවවන මස දුරුතු පොහෝ දින මහියංගණයට වැඩම කළහ."),
    q("නාගදීපයේ චූලෝදර-මහෝදර නා රජුන් දමනය කිරීමට බුදුරදුන් වැඩියේ කුමන පොහෝ දිනද?", "බක් පුන් පොහෝ දින", "දුරුතු පුන් පොහෝ දින", "වෙසක් පුන් පොහෝ දින", "ඇසළ පුන් පොහෝ දින", "බුද්ධත්වයෙන් පස්වන වස බක් පොහෝ දින නාගදීපයට වැඩම කළහ."),
    q("මණිඅක්ඛිත නා රජුගේ ආරාධනයෙන් බුදුරදුන් කැලණියට වැඩම කළේ කුමන පොහෝ දිනකදීද?", "වෙසක් පුන් පොහෝ දින", "පොසොන් පුන් පොහෝ දින", "ඇසළ පුන් පොහෝ දින", "බක් පුන් පොහෝ දින", "බුද්ධත්වයෙන් අටවන වස වෙසක් පොහෝ දින කැලණියට වැඩම කළහ."),
    q("නාලාගිරි ඇතු රජගහ නුවර වීදියේදී බුදුරදුන් දමනය කළේ කුමන බලයකින්ද?", "මෛත්‍රී බලයෙන්", "අසිපත් බලයෙන්", "මන්ත්‍ර බලයෙන්", "ශාරීරික ශක්තියෙන්", "රා බොන්නට දී එවූ නාලාගිරි ඇතු මෛත්‍රී කරුණාවෙන් දමනය කළහ."),
    q("සැරියුත් මහරහතන් වහන්සේ පිරිනිවන් පෑමට තෝරාගත් ස්ථානය කුමක්ද?", "උපන් නාලක ගමේ සූතිකාගාරය", "සැවැත් නුවර ජේතවනය", "රජගහ නුවර වේළුවනය", "කුසිනාරා නුවර සල් උයන", "තම මෑණියන් වූ රූපසාරී බැමිණිය සෝවාන් කර සැරියුත් හිමි උපන් ගමේදී පිරිනිවන් පෑහ."),
    q("සැරියුත් හිමි හා මුගලන් හිමි පිරිනිවන් පෑ පොහෝ දිනය කුමක්ද?", "ඉල් පුන් පොහෝ දින", "වප් පුන් පොහෝ දින", "උඳුවප් පුන් පොහෝ දින", "නිකිණි පුන් පොහෝ දින", "ඉල් පුන් පොහෝ දින අග්‍රශ්‍රාවක දෙනම පිරිනිවන් පෑ බව සඳහන් වේ."),
    q("ධම්මදින්නා මහරහත් තෙරණිය ධර්ම කථික භික්ෂුණීන් අතර අග්‍ර වීමට හේතු වූයේ කා සමඟ කළ ධර්ම සාකච්ඡාවද?", "විශාඛ උපාසක සමඟ", "අනේපිඬු සිටු සමඟ", "කොසොල් රජු සමඟ", "බිම්බිසාර රජු සමඟ", "ගිහි කල සැමියා වූ විශාඛ උපාසක ඇසූ ගැඹුරු ප්‍රශ්න චූලවේදල්ල සූත්‍රයෙන් විසඳූහ."),
    q("සිව්පිළිසිඹියාපත් මහරහතන් වහන්සේලා අතර කවිත්වයෙන් හා ප්‍රතිභානයෙන් අග්‍ර වූ හිමියන් කවුද?", "වංගීස හිමි", "රාධ හිමි", "මහා කොට්ඨිත හිමි", "සෝභිත හිමි", "බුදුරදුන් ඉදිරියේ ගාථා රචනා කර ප්‍රශංසා කළ වංගීස හිමි ප්‍රතිභානවන්තයන් අතර අග්‍ර විය."),
    q("ආලවක යක්ෂයා බුදුරදුන්ගෙන් ඇසූ ප්‍රශ්නවලට පිළිතුරු ලැබුණේ කවර සූත්‍රයෙන්ද?", "ආලවක සූත්‍රය", "සූචිලෝම සූත්‍රය", "හේමවත සූත්‍රය", "කසීභාරද්වාජ සූත්‍රය", "මිනිසාට ශ්‍රේෂ්ඨම ධනය ශ්‍රද්ධාව බව ආලවක සූත්‍රයේදී දේශනා කළහ."),
    q("කුඹුරු සානා අතරේදී බුදුරදුන් තමන් ද ගොවියෙකු බව දෙසූ සූත්‍රය දේශනා කළේ කා හටද?", "කසීභාරද්වාජ බමුණාට", "අග්ගික භාරද්වාජ බමුණාට", "සුන්දරික භාරද්වාජ බමුණාට", "පොක්ඛරසාති බමුණාට", "ශ්‍රද්ධාව බීජය ලෙසත් ප්‍රඥාව වියගහ ලෙසත් උපමා කර දේශනා කළහ."),
    q("ශරීරය පුරා ගෙඩි හටගත් විට බුදුරදුන් සියතින්ම උපස්ථාන කළ හිමියන් කවුද?", "පූතිගත්ත තිස්ස හිමි", "මහා කාල හිමි", "රාධ හිමි", "තේරක හිමි", "පූතිගත්ත තිස්ස හිමියන් අරභයා ගිලානෝපස්ථානයේ අගය වදාළහ."),
    q("බුදුරදුන්ගේ රූප ශෝභාවට ඇලී සිට පසුව ධර්මය දැකීමෙන් බුදුන් දැකිය යුතු බව වටහා ගත් හිමියන් කවුද?", "වක්කලී හිමි", "ඡන්න හිමි", "නන්ද හිමි", "උදායි හිමි", "'යෝ ධම්මං පස්සති සෝ මං පස්සති' යනුවෙන් වක්කලී හිමිට අවවාද කළහ."),
    q("මහා කාශ්‍යප හිමියන් හා භද්දා කාපිලානි තෙරණිය ගිහි කල කුමන ආකාරයේ සබඳතාවයක් පැවැත්වූවෝද?", "ස්වාමිපුරුෂයා හා බිරිඳ", "සොහොයුරා හා සොහොයුරිය", "පියා හා දියණිය", "ගුරුවරයා හා ශිෂ්‍යාව", "පිප්ඵලී මාණවක හා භද්දා කාපිලානි දෙදෙනාම කාමයෙන් වෙන්ව එකවර පැවිදි වූහ."),
    q("නිගණ්ඨ නාථපුත්තගේ ප්‍රධාන දායකයෙකුව සිට පසුව බුදු සසුන වැළඳගත් ගෘහපතිතුමා කවුද?", "උපාලි ගෘහපති", "සීහ සේනාපති", "මෙණ්ඩක සිටුතුමා", "ජෝතිය සිටුතුමා", "නාලන්දාවේ උපාලි ගෘහපති තර්කයෙන් පසු තෙරුවන් සරණ ගියේය."),
    q("රජගහ නුවර පාද සියුමැලි බැවින් රන් පාවහන් පැළඳ සිට පසුව වීර්යවන්ත භික්ෂූන් අතර අග්‍ර වූයේ කවුද?", "සෝණ කෝලිවිස හිමි", "මහා කාශ්‍යප හිමි", "රට්ඨපාල හිමි", "යස හිමි", "වීර්යය වැඩීමෙන් පා තුවාල වූ විට වීණා උපමාවෙන් අනුශාසනා ලැබීය."),
    q("බුදුරදුන්ට කපිලවස්තුවේදී වාසය සඳහා ශාක්‍යයන් විසින් ඉදිකර පූජා කළ ආරාමය කුමක්ද?", "නිග්‍රෝධාරාමය", "කූටාගාර ශාලාව", "ඝෝෂිතාරාමය", "බදරිකාරාමය", "නිග්‍රෝධාරාමයේදී රාහුල කුමරු දායාද ඉල්ලූ පසු පැවිදි කරන ලදී."),
    q("බුදුරදුන්ගෙන් ශාසනික දායාදය ඉල්ලීම සඳහා රාහුල කුමරු පිටත් කළේ කවුද?", "යසෝධරා දේවිය", "සුදොවුන් රජු", "මහා ප්‍රජාපතී ගෝතමිය", "නන්ද කුමරු", "ලෞකික දායාදයට වඩා උතුම් ආර්ය දායාදය වූ පැවිද්ද බුදුරදුන් ලබා දුන්හ."),
    q("දෙමාපිය අවසරය නොමැතිව උපවාස කර අවසර ලබාගෙන පැවිදි වූ රාජකීය කුමාරයා කවුද?", "රට්ඨපාල හිමි", "සුදින්න හිමි", "භද්දිය හිමි", "අනුරුද්ධ හිමි", "රට්ඨපාල හිමි කෝරව්‍ය රජුට ධර්මෝද්දේශ සතර දේශනා කළහ."),
    q("බුද්ධ ශාසනයේ දන් දෙන උපාසිකාවන් අතර අග්‍රස්ථානය ලැබූ කාන්තාව කවුද?", "විශාඛා මහා උපාසිකාව", "සුජාතා උපාසිකාව", "ඛුජ්ජුත්තරා උපාසිකාව", "වේළුකණ්ඨකී නන්දමාතා", "විශාඛාවන් අටවරයක් බුදුරදුන්ගෙන් ඉල්ලා සඟ සසුනට මහත් සේවයක් කළාය."),
    q("බහුශ්‍රුත උපාසිකාවන් අතර අග්‍රස්ථානය ලබා ඉතිවුත්තක සූත්‍ර දේශනා පැහැදිලි කළේ කවුද?", "ඛුජ්ජුත්තරා උපාසිකාව", "සාමාවතී දේවිය", "උත්තරා උපාසිකාව", "සුප්පියා උපාසිකාව", "සාමාවතී බිසවගේ සේවිකාවක වූ ඛුජ්ජුත්තරාව බණ අසා අන්තඃපුරයට දෙසුවාය.")
  )
}
